    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>80</sup> = 5<sup>78</sup> × 5<sup>2</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>80</sup> - 5<sup>78</sup> = 5<sup>78</sup>(5<sup>2</sup> - 1)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">5<sup>2</sup> - 1 = 24</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">5<sup>80</sup> - 5<sup>78</sup> = 24 × 5<sup>78</sup></span>"},{"quoi":"نُظهر القاسم 40","math":"<span dir=\"ltr\" class=\"expr\">24 × 5<sup>78</sup> = 40 × (3 × 5<sup>77</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">40 × 3 × 5<sup>77</sup></span> و منه يقبل القسمة على 40"}],
