    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>24</sup> = 5<sup>23</sup> × 5</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>24</sup> - 5<sup>23</sup> = 5<sup>23</sup>(5 - 1)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">5 - 1 = 4</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">5<sup>24</sup> - 5<sup>23</sup> = 4 × 5<sup>23</sup></span>"},{"quoi":"نُظهر القاسم 10","math":"<span dir=\"ltr\" class=\"expr\">4 × 5<sup>23</sup> = 10 × (2 × 5<sup>22</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">10 × 2 × 5<sup>22</sup></span> و منه يقبل القسمة على 10"}],
