    correction: [{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">8 = 4 × 2</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">36 = 4 × 9</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">8n + 36 = 4(2n + 9)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">4 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"}],
