    enonce: "بيّن أنّ العدد 1157607090 يقبل القسمة على 90",
    correction: [{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">90 = 10 × 9</span> و العددان أوليان فيما بينهما"},{"quoi":"شرط القسمة على 10","math":"العدد يقبل القسمة على 10 إذا كان رقم آحاده 0"},{"quoi":"نتحقّق من الشرط الأوّل","math":"نهاية العدد هي 0 و هي تقبل القسمة على 10"},{"quoi":"شرط القسمة على 9","math":"العدد يقبل القسمة على 9 إذا كان مجموع أرقامه يقبل القسمة على 9"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">1 + 1 + 5 + 7 + 6 + 0 + 7 + 0 + 9 + 0 = 36</span>"},{"quoi":"نتحقّق من الشرط الثاني","math":"36 يقبل القسمة على 9"},{"quoi":"النتيجة","math":"العدد يقبل القسمة على 10 و على 9 و هما أوليان فيما بينهما، فهو يقبل القسمة على 90"}],
