    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>1154</sup> + n × 3<sup>1151</sup> = 3<sup>1151</sup>(3<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">39 = 3 × 13</span>"},{"quoi":"العامل 3 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">3<sup>1151</sup> = 3 × 3<sup>1150</sup></span>"},{"quoi":"يبقى الشرط على 13","math":"بما أنّ 13 و 3 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">3<sup>3</sup> + n</span> القسمة على 13"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">3<sup>3</sup> = 27</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">27 + n</span> القسمة على 13"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 12 ؛ 25 ؛ 38 ؛ 51</span>"}],
