    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">25<sup>358</sup> = 5<sup>716</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>718</sup> + n × 5<sup>716</sup> = 5<sup>716</sup>(5<sup>2</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">35 = 5 × 7</span>"},{"quoi":"العامل 5 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">5<sup>716</sup> = 5 × 5<sup>715</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 5 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">5<sup>2</sup> + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">5<sup>2</sup> = 25</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 30 بحيث يقبل <span dir=\"ltr\" class=\"expr\">25 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 3 ؛ 10 ؛ 17 ؛ 24</span>"}],
